// 🧹 清洗解析 DeepSeek 响应
const raw = items[0].json.choices[0].message.content;

// 去除非法字符
const clean = raw.replace(/```json/g, '').replace(/```/g, '').trim();

// 解析成对象
let data = {};
try {
  data = JSON.parse(clean);
} catch (e) {
  console.error('JSON解析错误:', e);
  console.error('原始内容:', raw);
  data = {
    sections: []
  };
}

// 获取参数
const params = $('🔧 解析参数').first().json;

// 确保sections存在
if (!data.sections || !Array.isArray(data.sections)) {
  data.sections = [];
}

// 输出纯净数据
return [{
  json: {
    exam_type: params.examType,
    target_language: params.targetLanguage,
    level: params.level,
    category: params.category,
    user_id: params.userId,
    request_id: params.requestId,
    sections: data.sections,
    raw_response: clean
  }
}];

const examTypes = $('⚙️ 默认配置').first().json.exam_types.split(',');

// 为每种考试类型生成一个任务
const items = examTypes.map((type, index) => ({
  json: {
    body: {
      targetLanguage: ['HSK', 'BCT', 'TOCFL'].includes(type.trim()) ? 'Chinese' : 'English',
      examType: type.trim(),
      level: getDefaultLevel(type.trim()),
      category: type.trim(),
      userId: 'system',
      requestId: `scheduled_${Date.now()}_${index}`
    }
  }
}));

function getDefaultLevel(examType) {
  const defaults = {
    'HSK': 'Level 3',
    'BCT': 'Level A',
    'TOCFL': 'Level 3',
    'IELTS': 'Band 6.0',
    'TOEFL': '61-90',
    'CET-4': 'Level 2',
    'CET-6': 'Level 2'
  };
  return defaults[examType] || 'Intermediate';
}

return items;
